-- V70 soil profiles rebuilt from the current live trail centers.
-- Run nationwide-foundation.sql before this seed.

begin;
set local search_path = public, extensions;

on conflict (trail_id, geometry_version)
do update set
  profile = excluded.profile,
  confidence = excluded.confidence,
  usable_samples = excluded.usable_samples,
  research_location = excluded.research_location,
  calculated_at = excluded.calculated_at;

commit;
